"""Tests for conversation threads, messages, and notes (Section 20 Item #8)."""

import uuid
from datetime import datetime, timezone

import pytest
from sqlalchemy.ext.asyncio import AsyncSession

from app.models.conversation import ConversationThread, ConversationMessage, ConversationNote


# ── Fixtures ──────────────────────────────────────────────────

def _thread(workspace_id: uuid.UUID, **kwargs) -> ConversationThread:
    return ConversationThread(
        id=uuid.uuid4(),
        workspace_id=workspace_id,
        channel=kwargs.get("channel", "email"),
        subject=kwargs.get("subject", "Test Thread"),
        status=kwargs.get("status", "open"),
        is_read=kwargs.get("is_read", False),
        **{k: v for k, v in kwargs.items() if k not in ("channel", "subject", "status", "is_read")},
    )


def _message(thread_id: uuid.UUID, **kwargs) -> ConversationMessage:
    return ConversationMessage(
        id=uuid.uuid4(),
        thread_id=thread_id,
        direction=kwargs.get("direction", "inbound"),
        channel=kwargs.get("channel", "email"),
        body=kwargs.get("body", "Hello there"),
        sender_email=kwargs.get("sender_email", "lead@example.com"),
    )


def _note(workspace_id: uuid.UUID, thread_id: uuid.UUID | None = None, **kwargs) -> ConversationNote:
    return ConversationNote(
        id=uuid.uuid4(),
        workspace_id=workspace_id,
        thread_id=thread_id,
        note_type=kwargs.get("note_type", "manual"),
        body=kwargs.get("body", "A note"),
    )


# ── Model Tests ───────────────────────────────────────────────

class TestConversationThread:
    def test_create_thread(self):
        ws_id = uuid.uuid4()
        t = _thread(ws_id, subject="Re: Intro", channel="email")
        assert t.channel == "email"
        assert t.subject == "Re: Intro"
        assert t.status == "open"
        assert t.is_read is False

    def test_linkedin_thread(self):
        ws_id = uuid.uuid4()
        t = _thread(ws_id, channel="linkedin", subject=None)
        assert t.channel == "linkedin"
        assert t.subject is None

    def test_thread_default_status(self):
        ws_id = uuid.uuid4()
        t = _thread(ws_id)
        assert t.status == "open"

    def test_thread_with_provider_id(self):
        ws_id = uuid.uuid4()
        t = _thread(ws_id, provider_thread_id="gmail_thread_abc123")
        assert t.provider_thread_id == "gmail_thread_abc123"

    def test_thread_with_lead_and_campaign(self):
        ws_id = uuid.uuid4()
        lead_id = uuid.uuid4()
        campaign_id = uuid.uuid4()
        t = _thread(ws_id, lead_id=lead_id, campaign_id=campaign_id)
        assert t.lead_id == lead_id
        assert t.campaign_id == campaign_id


class TestConversationMessage:
    def test_create_inbound_message(self):
        tid = uuid.uuid4()
        m = _message(tid, direction="inbound", body="Hi there")
        assert m.direction == "inbound"
        assert m.body == "Hi there"
        assert m.thread_id == tid

    def test_create_outbound_message(self):
        tid = uuid.uuid4()
        m = _message(tid, direction="outbound", sender_email="me@co.com")
        assert m.direction == "outbound"
        assert m.sender_email == "me@co.com"

    def test_message_with_provider_id(self):
        tid = uuid.uuid4()
        m = _message(tid)
        m.provider_message_id = "msg_12345"
        assert m.provider_message_id == "msg_12345"

    def test_message_with_metadata(self):
        tid = uuid.uuid4()
        m = _message(tid)
        m.metadata_json = {"headers": {"X-Custom": "val"}}
        assert m.metadata_json["headers"]["X-Custom"] == "val"

    def test_message_linkedin_channel(self):
        tid = uuid.uuid4()
        m = _message(tid, channel="linkedin", body="LinkedIn msg")
        assert m.channel == "linkedin"


class TestConversationNote:
    def test_create_manual_note(self):
        ws_id = uuid.uuid4()
        n = _note(ws_id, body="Follow up tomorrow")
        assert n.note_type == "manual"
        assert n.body == "Follow up tomorrow"
        assert n.workspace_id == ws_id

    def test_ai_note(self):
        ws_id = uuid.uuid4()
        n = _note(ws_id, note_type="ai", body="Lead seems interested")
        assert n.note_type == "ai"

    def test_system_note(self):
        ws_id = uuid.uuid4()
        n = _note(ws_id, note_type="system", body="Status changed to replied")
        assert n.note_type == "system"

    def test_workflow_note(self):
        ws_id = uuid.uuid4()
        wf_id = uuid.uuid4()
        n = _note(ws_id, note_type="workflow", body="Auto-generated by workflow")
        n.workflow_id = wf_id
        n.node_id = "node_add_note_1"
        assert n.workflow_id == wf_id
        assert n.node_id == "node_add_note_1"

    def test_note_without_thread(self):
        ws_id = uuid.uuid4()
        n = _note(ws_id, thread_id=None, body="Standalone lead note")
        assert n.thread_id is None

    def test_note_with_thread(self):
        ws_id = uuid.uuid4()
        tid = uuid.uuid4()
        n = _note(ws_id, thread_id=tid, body="Thread note")
        assert n.thread_id == tid

    def test_note_with_author(self):
        ws_id = uuid.uuid4()
        author_id = uuid.uuid4()
        n = _note(ws_id, body="User note")
        n.author_id = author_id
        assert n.author_id == author_id

    def test_note_with_lead(self):
        ws_id = uuid.uuid4()
        lead_id = uuid.uuid4()
        n = _note(ws_id, body="Lead-specific note")
        n.lead_id = lead_id
        assert n.lead_id == lead_id


# ── Integration: Thread + Messages + Notes together ──────────

class TestConversationIntegration:
    def test_thread_messages_notes_structure(self):
        """Verify the full hierarchy: thread → messages + notes."""
        ws_id = uuid.uuid4()
        t = _thread(ws_id, subject="Sales conversation")

        m1 = _message(t.id, direction="outbound", body="Hi, are you interested?")
        m2 = _message(t.id, direction="inbound", body="Yes, tell me more")

        n1 = _note(ws_id, thread_id=t.id, body="Lead is warm")
        n2 = _note(ws_id, thread_id=t.id, note_type="ai", body="Positive sentiment detected")

        # Verify structure
        assert m1.thread_id == t.id
        assert m2.thread_id == t.id
        assert n1.thread_id == t.id
        assert n2.thread_id == t.id
        assert n2.note_type == "ai"

    def test_multi_channel_thread_structure(self):
        """Email and LinkedIn threads for same workspace."""
        ws_id = uuid.uuid4()
        lead_id = uuid.uuid4()

        email_thread = _thread(ws_id, channel="email", subject="Re: Partnership", lead_id=lead_id)
        li_thread = _thread(ws_id, channel="linkedin", subject=None, lead_id=lead_id)

        assert email_thread.channel == "email"
        assert li_thread.channel == "linkedin"
        assert email_thread.lead_id == li_thread.lead_id
